package br.com.onda;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.net.Uri;import android.os.*;import androidx.core.content.ContextCompat;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** One explicit foreground job. No automatic retries, mic, or periodic scans. */
@androidx.media3.common.util.UnstableApi
public class MemoryIndexService extends Service {
 static final int NOTICE=908;private static final String CHANNEL="onda-memory";private static volatile MemoryIndexService live;
 interface Listener{void changed();}private static final Set<Listener> observers=new CopyOnWriteArraySet<>();
 static volatile boolean running;static volatile String message="Escolha os arquivos que deseja lembrar.";
 static void listen(Listener l){observers.add(l);}static void forget(Listener l){observers.remove(l);}
 static boolean start(Context c,MemoryStore.Source source,boolean prepare){if(running||live!=null&&live.finished)return false;Intent i=new Intent(c,MemoryIndexService.class).putExtra("prepare",prepare);if(source!=null){i.putExtra("uri",source.uri).putExtra("sidecar",source.sidecar).putExtra("name",source.name).putExtra("kind",source.kind);ClipData clip=null;if("content".equals(Uri.parse(source.uri).getScheme()))clip=ClipData.newRawUri("Arquivo escolhido",Uri.parse(source.uri));if(!source.sidecar.isEmpty()&&"content".equals(Uri.parse(source.sidecar).getScheme())){if(clip==null)clip=ClipData.newRawUri("Legenda escolhida",Uri.parse(source.sidecar));else clip.addItem(new ClipData.Item(Uri.parse(source.sidecar)));}if(clip!=null){i.setClipData(clip);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);}}ContextCompat.startForegroundService(c,i);return true;}
 static void cancel(){MemoryIndexService service=live;if(service!=null){service.cancelled=true;Thread t=service.processing;if(t!=null)t.interrupt();MemoryAudio.Recognizer engine=MemoryAudio.active;if(engine!=null)engine.cancel();service.update("Cancelando…",true);}}
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private volatile boolean cancelled,finished;private volatile Thread processing;private PowerManager.WakeLock wake;private long lastNotice;
 public IBinder onBind(Intent intent){return null;}
 public void onCreate(){super.onCreate();live=this;((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel(CHANNEL,"Memória multimídia",NotificationManager.IMPORTANCE_LOW));}
 public int onStartCommand(Intent intent,int flags,int id){if(intent==null){stopSelf();return START_NOT_STICKY;}if("cancel".equals(intent.getAction())){cancel();if(!running)stopSelf();return START_NOT_STICKY;}if(running)return START_NOT_STICKY;running=true;boolean prepare=intent.getBooleanExtra("prepare",false);message=prepare?"Preparando reconhecimento de voz…":"Indexando arquivo no celular…";getSharedPreferences("memory_job",0).edit().putBoolean("running",true).putString("message",message).apply();
  try{if(Build.VERSION.SDK_INT>=35)startForeground(NOTICE,notice(true),!prepare&&("speech".equals(intent.getStringExtra("kind"))||"audio".equals(intent.getStringExtra("kind")))?ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROCESSING:ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC);else if(Build.VERSION.SDK_INT>=29)startForeground(NOTICE,notice(true),ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC);else startForeground(NOTICE,notice(true));wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"Onda:MemoryIndex");wake.acquire();}catch(RuntimeException error){finish("Não foi possível iniciar o processamento. Volte à tela e tente novamente.");return START_NOT_STICKY;}
  worker.execute(()->{processing=Thread.currentThread();android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);try{check();if(prepare){LiveSpeechModels.obtain(this,LiveSpeechModels.Model.BASE,true,()->cancelled,(at,total)->progress("Baixando modelo por Wi-Fi",at,total));check();finish("Modelo de voz pronto. Escolha um áudio ou vídeo para transcrever.");}else{String uri=intent.getStringExtra("uri"),kind=intent.getStringExtra("kind"),side=intent.getStringExtra("sidecar");if(uri==null||!Arrays.asList("pdf","subtitle","subtitle_audio","speech","audio").contains(kind))throw new IOException("Pedido inválido");MemoryStore.Source source=MemoryStore.source(this,Uri.parse(uri),side==null||side.isEmpty()?null:Uri.parse(side),intent.getStringExtra("name"),kind);int count=MemoryIndexer.index(this,source,new MemoryIndexer.Control(){public void check()throws IOException{MemoryIndexService.this.check();}public void progress(String text,long at,long total){MemoryIndexService.this.progress(text,at,total);}});finish(count+" trechos indexados. Busque por palavras do conteúdo.");}}catch(Exception|LinkageError|OutOfMemoryError error){finish(cancelled?"Análise cancelada. O índice anterior foi preservado.":"Não foi possível indexar: "+(error.getMessage()==null?"formato ou memória indisponível neste aparelho":error.getMessage()));}finally{processing=null;}});return START_NOT_STICKY;
 }
 private void check()throws IOException{if(cancelled||Thread.currentThread().isInterrupted())throw new InterruptedIOException("Cancelado");}
 private void progress(String text,long at,long total){long now=SystemClock.elapsedRealtime();if(now-lastNotice<750)return;lastNotice=now;update(text+(total>0?" • "+Math.min(100,at*100/total)+"%":""),true);}
 private void update(String text,boolean active){main.post(()->{if(finished)return;message=text;((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(NOTICE,notice(active));for(Listener l:observers)l.changed();});}
 private void finish(String text){main.post(()->{if(finished)return;finished=true;running=false;message=text;getSharedPreferences("memory_job",0).edit().putBoolean("running",false).putString("message",text).apply();stopForeground(STOP_FOREGROUND_DETACH);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(NOTICE,notice(false));for(Listener l:observers)l.changed();if(wake!=null&&wake.isHeld())wake.release();stopSelf();});}
 private Notification notice(boolean active){PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MemoryActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.ic_menu_search).setContentTitle("Memória Multimídia").setContentText(message).setContentIntent(open).setOngoing(active).setOnlyAlertOnce(true);if(active){PendingIntent cancel=PendingIntent.getService(this,0,new Intent(this,MemoryIndexService.class).setAction("cancel"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);b.addAction(new Notification.Action.Builder(null,"Cancelar",cancel).build());}return b.build();}
 @Override public void onTimeout(int startId,int type){cancel();}
 public void onDestroy(){cancelled=true;running=false;MemoryAudio.Recognizer engine=MemoryAudio.active;if(engine!=null)engine.cancel();worker.shutdownNow();if(wake!=null&&wake.isHeld())wake.release();if(live==this)live=null;super.onDestroy();}
}
